<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Expense Tracker</title>
<style>
  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
  body { font-family: system-ui, sans-serif; background: #f0f2f5; color: #1a1a2e; min-height: 100vh; padding: 24px 16px; }
  h1 { font-size: 1.5rem; font-weight: 700; margin-bottom: 24px; }
  h2 { font-size: 1rem; font-weight: 600; margin-bottom: 12px; color: #444; }
  .card { background: #fff; border-radius: 10px; padding: 20px; margin-bottom: 20px; box-shadow: 0 1px 4px rgba(0,0,0,0.08); }
  .form-row { display: flex; flex-wrap: wrap; gap: 10px; margin-bottom: 10px; }
  .form-group { display: flex; flex-direction: column; gap: 4px; flex: 1 1 140px; }
  label { font-size: 0.78rem; font-weight: 600; color: #555; text-transform: uppercase; letter-spacing: .04em; }
  input, select { border: 1px solid #d1d5db; border-radius: 6px; padding: 8px 10px; font-size: 0.95rem; background: #fafafa; color: inherit; width: 100%; }
  input:focus, select:focus { outline: 2px solid #6366f1; border-color: transparent; background: #fff; }
  .form-group.note { flex: 2 1 240px; }
  #add-expense { padding: 9px 22px; background: #6366f1; color: #fff; border: none; border-radius: 6px; font-size: 0.95rem; font-weight: 600; cursor: pointer; align-self: flex-end; white-space: nowrap; }
  #add-expense:hover { background: #4f46e5; }
  #form-error { color: #dc2626; font-size: 0.85rem; min-height: 1.2em; margin-top: 4px; }
  .filters { display: flex; flex-wrap: wrap; gap: 10px; align-items: flex-end; }
  .filters .form-group { flex: 1 1 120px; }
  .summary-grid { display: flex; flex-wrap: wrap; gap: 10px; }
  .cat-total { flex: 1 1 100px; background: #f5f3ff; border: 1px solid #e0e7ff; border-radius: 8px; padding: 10px 14px; font-size: 0.88rem; }
  .cat-total span { display: block; font-size: 0.72rem; text-transform: uppercase; letter-spacing: .05em; color: #7c3aed; font-weight: 700; margin-bottom: 2px; }
  #total-row { display: flex; align-items: center; justify-content: space-between; padding: 10px 0 4px; }
  #total-row strong { font-size: 0.9rem; color: #555; }
  #total { font-size: 1.3rem; font-weight: 700; color: #1a1a2e; }
  #expense-list { list-style: none; display: flex; flex-direction: column; gap: 8px; }
  .expense { display: flex; align-items: center; gap: 10px; padding: 10px 14px; border: 1px solid #e5e7eb; border-radius: 8px; background: #fafafa; }
  .exp-amount { font-weight: 700; font-size: 1rem; min-width: 70px; }
  .exp-cat { font-size: 0.78rem; font-weight: 600; text-transform: uppercase; letter-spacing: .04em; padding: 2px 8px; border-radius: 20px; background: #e0e7ff; color: #4338ca; white-space: nowrap; }
  .exp-date { font-size: 0.82rem; color: #6b7280; white-space: nowrap; }
  .exp-note { font-size: 0.85rem; color: #555; flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .exp-del { margin-left: auto; background: none; border: 1px solid #fca5a5; color: #ef4444; border-radius: 6px; padding: 3px 10px; cursor: pointer; font-size: 0.8rem; white-space: nowrap; flex-shrink: 0; }
  .exp-del:hover { background: #fef2f2; }
  .empty { color: #9ca3af; font-size: 0.9rem; text-align: center; padding: 20px 0; }
</style>
</head>
<body>
<h1>Expense Tracker</h1>

<div class="card">
  <h2>Add Expense</h2>
  <div class="form-row">
    <div class="form-group">
      <label for="amount">Amount</label>
      <input type="number" id="amount" min="0.01" step="0.01" placeholder="0.00">
    </div>
    <div class="form-group">
      <label for="category">Category</label>
      <select id="category">
        <option value="groceries">Groceries</option>
        <option value="transport">Transport</option>
        <option value="bills">Bills</option>
        <option value="fun">Fun</option>
      </select>
    </div>
    <div class="form-group">
      <label for="date">Date</label>
      <input type="date" id="date">
    </div>
    <div class="form-group note">
      <label for="note">Note (optional)</label>
      <input type="text" id="note" placeholder="What was this for?">
    </div>
    <button id="add-expense">Add</button>
  </div>
  <div id="form-error"></div>
</div>

<div class="card">
  <h2>Filters</h2>
  <div class="filters">
    <div class="form-group">
      <label for="filter-category">Category</label>
      <select id="filter-category">
        <option value="all">All</option>
        <option value="groceries">Groceries</option>
        <option value="transport">Transport</option>
        <option value="bills">Bills</option>
        <option value="fun">Fun</option>
      </select>
    </div>
    <div class="form-group">
      <label for="filter-from">From</label>
      <input type="date" id="filter-from">
    </div>
    <div class="form-group">
      <label for="filter-to">To</label>
      <input type="date" id="filter-to">
    </div>
  </div>
</div>

<div class="card">
  <h2>Summary</h2>
  <div class="summary-grid">
    <div class="cat-total" data-cat="groceries"><span>Groceries</span><span class="cat-val">0.00</span></div>
    <div class="cat-total" data-cat="transport"><span>Transport</span><span class="cat-val">0.00</span></div>
    <div class="cat-total" data-cat="bills"><span>Bills</span><span class="cat-val">0.00</span></div>
    <div class="cat-total" data-cat="fun"><span>Fun</span><span class="cat-val">0.00</span></div>
  </div>
  <div id="total-row">
    <strong>Visible Total</strong>
    <span id="total">0.00</span>
  </div>
</div>

<div class="card">
  <h2>Expenses</h2>
  <ul id="expense-list"></ul>
</div>

<script>
  const CATEGORIES = ['groceries', 'transport', 'bills', 'fun'];
  const LS_KEY = 'expense-tracker-v1';

  let expenses = [];

  function load() {
    try { expenses = JSON.parse(localStorage.getItem(LS_KEY)) || []; } catch { expenses = []; }
  }

  function save() {
    localStorage.setItem(LS_KEY, JSON.stringify(expenses));
  }

  function getFilters() {
    return {
      category: document.getElementById('filter-category').value,
      from: document.getElementById('filter-from').value,
      to: document.getElementById('filter-to').value,
    };
  }

  function isVisible(exp, filters) {
    if (filters.category !== 'all' && exp.category !== filters.category) return false;
    if (filters.from && exp.date < filters.from) return false;
    if (filters.to && exp.date > filters.to) return false;
    return true;
  }

  function render() {
    const filters = getFilters();
    const list = document.getElementById('expense-list');
    list.innerHTML = '';

    const catTotals = Object.fromEntries(CATEGORIES.map(c => [c, 0]));
    let total = 0;
    let anyVisible = false;

    const sorted = [...expenses].reverse();

    sorted.forEach(exp => {
      const visible = isVisible(exp, filters);
      if (visible) {
        total += exp.amount;
        catTotals[exp.category] = (catTotals[exp.category] || 0) + exp.amount;
        anyVisible = true;

        const li = document.createElement('li');
        li.className = 'expense';
        li.dataset.id = exp.id;
        li.innerHTML = `
          <span class="exp-amount">$${exp.amount.toFixed(2)}</span>
          <span class="exp-cat">${exp.category}</span>
          <span class="exp-date">${exp.date}</span>
          ${exp.note ? `<span class="exp-note">${escHtml(exp.note)}</span>` : '<span class="exp-note"></span>'}
          <button class="exp-del" data-id="${exp.id}">Delete</button>
        `;
        list.appendChild(li);
      }
    });

    if (!anyVisible) {
      const li = document.createElement('li');
      li.className = 'empty';
      li.textContent = expenses.length === 0 ? 'No expenses yet. Add one above.' : 'No expenses match the current filters.';
      list.appendChild(li);
    }

    document.getElementById('total').textContent = total.toFixed(2);

    CATEGORIES.forEach(cat => {
      const el = document.querySelector(`.cat-total[data-cat="${cat}"] .cat-val`);
      if (el) el.textContent = (catTotals[cat] || 0).toFixed(2);
    });
  }

  function escHtml(str) {
    return str.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  }

  document.getElementById('add-expense').addEventListener('click', () => {
    const amountRaw = document.getElementById('amount').value.trim();
    const category = document.getElementById('category').value;
    const date = document.getElementById('date').value;
    const note = document.getElementById('note').value.trim();
    const errEl = document.getElementById('form-error');

    const amount = parseFloat(amountRaw);
    if (!amountRaw || isNaN(amount) || amount <= 0) {
      errEl.textContent = 'Please enter a valid positive amount.';
      return;
    }
    if (!date) {
      errEl.textContent = 'Please select a date.';
      return;
    }

    errEl.textContent = '';
    expenses.push({ id: Date.now().toString(36) + Math.random().toString(36).slice(2), amount, category, date, note });
    save();
    document.getElementById('amount').value = '';
    document.getElementById('note').value = '';
    render();
  });

  document.getElementById('expense-list').addEventListener('click', e => {
    const btn = e.target.closest('.exp-del');
    if (!btn) return;
    const id = btn.dataset.id;
    expenses = expenses.filter(ex => ex.id !== id);
    save();
    render();
  });

  ['filter-category', 'filter-from', 'filter-to'].forEach(id => {
    document.getElementById(id).addEventListener('change', render);
  });

  load();
  render();
</script>
</body>
</html>
